        reg_rdata_next[0] = ctrl_zeroize_qs;
        reg_rdata_next[1] = ctrl_sel_qs;
        reg_rdata_next[2] = ctrl_encdec_qs;
        reg_rdata_next[3] = ctrl_keylen_qs;
        reg_rdata_next[4] = ctrl_init_qs;
        reg_rdata_next[5] = ctrl_next_qs;
      end

      addr_hit[1]: begin
        reg_rdata_next[0] = status_ready_qs;
        reg_rdata_next[1] = status_result_valid_qs;
        reg_rdata_next[2] = status_keccak_done_qs;
      end

      addr_hit[2]: begin
